"Storage engine per shard with ordered key-value storage and range query support.

Uses a sorted list of keys with bisect for O(log n) range queries.
Values are lists of document IDs (for search engine keyword indexing).
Supports hot key detection and dynamic replication hints.
"""

import bisect
import threading
import time
from collections import OrderedDict, defaultdict
from typing import Any, Dict, List, Optional, Tuple


class StorageEngine:
    def __init__(self, hot_key_threshold: int = 1000):
        self._data: Dict[str, List[Any]] = {}
        self._sorted_keys: List[str] = []
        self._lock = threading.RLock()
        self._hot_key_threshold = hot_key_threshold
        self._access_counts: Dict[str, int] = defaultdict(int)
        self._write_counts: Dict[str, int] = defaultdict(int)
        self._access_window_start = time.monotonic()
        self._window_duration = 60.0

    def put(self, key: str, value: Any):
        with self._lock:
            if key not in self._data:
                self._data[key] = []
                bisect.insort(self._sorted_keys, key)
            self._data[key].append(value)
            self._write_counts[key] += 1

    def get(self, key: str) -> Optional[List[Any]]:
        with self._lock:
            self._access_counts[key] += 1
            self._maybe_rotate_window()
            return self._data.get(key)

    def range_query(
        self, start: str, end: str, inclusive: bool = True
    ) -> List[Tuple[str, List[Any]]]:
        with self._lock:
            if inclusive:
                left = bisect.bisect_left(self._sorted_keys, start)
                right = bisect.bisect_right(self._sorted_keys, end)
            else:
                left = bisect.bisect_right(self._sorted_keys, start)
                right = bisect.bisect_left(self._sorted_keys, end)
            keys = self._sorted_keys[left:right]
            return [(k, self._data[k]) for k in keys]

    def prefix_scan(self, prefix: str) -> List[Tuple[str, List[Any]]]:
        with self._lock:
            left = bisect.bisect_left(self._sorted_keys, prefix)
            result = []
            for i in range(left, len(self._sorted_keys)):
                k = self._sorted_keys[i]
                if not k.startswith(prefix):
                    break
                result.append((k, self._data[k]))
            return result

    def batch_put(self, entries: List[Tuple[str, Any]]):
        with self._lock:
            for key, value in entries:
                if key not in self._data:
                    self._data[key] = []
                    bisect.insort(self._sorted_keys, key)
                self._data[key].append(value)
                self._write_counts[key] += 1

    def remove(self, key: str) -> bool:
        with self._lock:
            if key in self._data:
                del self._data[key]
                self._sorted_keys.remove(key)
                self._access_counts.pop(key, None)
                self._write_counts.pop(key, None)
                return True
            return False

    def contains(self, key: str) -> bool:
        with self._lock:
            return key in self._data

    def key_count(self) -> int:
        with self._lock:
            return len(self._sorted_keys)

    def total_values(self) -> int:
        with self._lock:
            return sum(len(v) for v in self._data.values())

    def get_all_keys(self) -> List[str]:
        with self._lock:
            return list(self._sorted_keys)

    def get_snapshot(self) -> Dict[str, List[Any]]:
        with self._lock:
            return {k: list(v) for k, v in self._data.items()}

    def get_hot_keys(self, top_n: int = 10) -> List[Tuple[str, int]]:
        with self._lock:
            self._maybe_rotate_window()
            sorted_keys = sorted(
                self._access_counts.items(), key=lambda x: x[1], reverse=True
            )
            return sorted_keys[:top_n]

    def get_hot_write_keys(self, top_n: int = 10) -> List[Tuple[str, int]]:
        with self._lock:
            self._maybe_rotate_window()
            sorted_keys = sorted(
                self._write_counts.items(), key=lambda x: x[1], reverse=True
            )
            return sorted_keys[:top_n]

    def _maybe_rotate_window(self):
        now = time.monotonic()
        if now - self._access_window_start > self._window_duration:
            self._access_counts.clear()
            self._write_counts.clear()
            self._access_window_start = now

    def __len__(self) -> int:
        return self.key_count()

"Consistent hashing ring with virtual nodes.

Maps keys to shards using a hash ring with configurable virtual nodes
per physical node for balanced distribution.
"""

import hashlib
from bisect import bisect_right
from typing import Any, Dict, List, Optional, Set, Tuple


class ConsistentHashRing:
    def __init__(self, virtual_nodes_per_shard: int = 150):
        self._ring: List[Tuple[int, str]] = []
        self._positions: Dict[int, str] = {}
        self._nodes: Set[str] = set()
        self._shard_keys: Dict[str, List[int]] = {}
        self._virtual_nodes_per_shard = virtual_nodes_per_shard

    def add_shard(self, shard_id: str):
        if shard_id in self._nodes:
            return
        self._nodes.add(shard_id)
        self._shard_keys[shard_id] = []
        for i in range(self._virtual_nodes_per_shard):
            vn_key = f"{shard_id}:vn:{i}"
            pos = self._hash(vn_key)
            self._ring.append((pos, shard_id))
            self._shard_keys[shard_id].append(pos)
        self._ring.sort(key=lambda x: x[0])

    def remove_shard(self, shard_id: str):
        if shard_id not in self._nodes:
            return
        self._nodes.discard(shard_id)
        self._ring = [(p, n) for p, n in self._ring if n != shard_id]
        self._shard_keys.pop(shard_id, None)

    def get_shard(self, key: str) -> Optional[str]:
        if not self._ring:
            return None
        h = self._hash(key)
        pos = bisect_right([p for p, _ in self._ring], h)
        if pos == len(self._ring):
            pos = 0
        return self._ring[pos][1]

    def get_shards(self, key: str, count: int) -> List[str]:
        if not self._ring or count <= 0:
            return []
        h = self._hash(key)
        pos = bisect_right([p for p, _ in self._ring], h)
        if pos == len(self._ring):
            pos = 0
        seen: Set[str] = set()
        result = []
        for i in range(len(self._ring)):
            idx = (pos + i) % len(self._ring)
            shard = self._ring[idx][1]
            if shard not in seen:
                seen.add(shard)
                result.append(shard)
                if len(result) >= count:
                    break
        return result

    def get_all_shards(self) -> List[str]:
        return sorted(self._nodes)

    def shard_count(self) -> int:
        return len(self._nodes)

    def keys_moving(self, added: List[str] = None, removed: List[str] = None) -> float:
        added = added or []
        removed = removed or []
        temp_ring = ConsistentHashRing(self._virtual_nodes_per_shard)
        for n in self._nodes | set(added) - set(removed):
            temp_ring.add_shard(n)
        moved = 0
        sample = 10000
        for i in range(sample):
            key = f"__sample__{i}"
            orig = self.get_shard(key)
            new = temp_ring.get_shard(key)
            if orig != new:
                moved += 1
        return moved / sample

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16) & 0x7FFFFFFF

"Individual node in the distributed KV cluster.

Manages a local StorageEngine, optional write-ahead log,
replication to peer nodes, and health status.
"""

import json
import os
import threading
import time
from typing import Any, List, Optional, Tuple

from .engine import StorageEngine


class WALEntry:
    __slots__ = ("op", "key", "value", "timestamp")

    def __init__(self, op: str, key: str, value: Any = None):
        self.op = op
        self.key = key
        self.value = value
        self.timestamp = time.time()


class Node:
    def __init__(
        self,
        node_id: str,
        wal_path: Optional[str] = None,
        engine: Optional[StorageEngine] = None,
    ):
        self.node_id = node_id
        self.engine = engine or StorageEngine()
        self._wal_path = wal_path
        self._wal_lock = threading.Lock()
        self._healthy = True
        self._replicas: List["Node"] = []
        self._stats = {"gets": 0, "puts": 0, "errors": 0, "replicated": 0}
        self._stats_lock = threading.Lock()

    def put(self, key: str, value: Any, replicate: bool = True) -> bool:
        try:
            self.engine.put(key, value)
            self._wal_append("put", key, value)
            with self._stats_lock:
                self._stats["puts"] += 1
            if replicate and self._replicas:
                self._replicate("put", key, value)
            return True
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return False

    def get(self, key: str) -> Optional[List[Any]]:
        try:
            result = self.engine.get(key)
            with self._stats_lock:
                self._stats["gets"] += 1
            return result
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return None

    def range_query(
        self, start: str, end: str, inclusive: bool = True
    ) -> List[Tuple[str, List[Any]]]:
        try:
            return self.engine.range_query(start, end, inclusive)
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return []

    def prefix_scan(self, prefix: str) -> List[Tuple[str, List[Any]]]:
        try:
            return self.engine.prefix_scan(prefix)
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return []

    def batch_put(
        self, entries: List[Tuple[str, Any]], replicate: bool = True
    ) -> bool:
        try:
            self.engine.batch_put(entries)
            for key, value in entries:
                self._wal_append("put", key, value)
            with self._stats_lock:
                self._stats["puts"] += len(entries)
            if replicate and self._replicas:
                for key, value in entries:
                    self._replicate("put", key, value)
            return True
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return False

    def remove(self, key: str) -> bool:
        try:
            result = self.engine.remove(key)
            if result:
                self._wal_append("remove", key)
            return result
        except Exception:
            with self._stats_lock:
                self._stats["errors"] += 1
            return False

    def contains(self, key: str) -> bool:
        return self.engine.contains(key)

    def add_replica(self, replica: "Node"):
        if replica not in self._replicas and replica != self:
            self._replicas.append(replica)

    def remove_replica(self, replica: "Node"):
        if replica in self._replicas:
            self._replicas.remove(replica)

    def get_replicas(self) -> List["Node"]:
        return list(self._replicas)

    def get_snapshot(self) -> dict:
        return {
            "node_id": self.node_id,
            "key_count": self.engine.key_count(),
            "total_values": self.engine.total_values(),
            "keys": self.engine.get_all_keys(),
            "data": self.engine.get_snapshot(),
            "hot_keys": self.engine.get_hot_keys(),
            "stats": self.get_stats(),
            "healthy": self._healthy,
            "replicas": [r.node_id for r in self._replicas],
        }

    def get_data_snapshot(self) -> dict:
        return self.engine.get_snapshot()

    def get_stats(self) -> dict:
        with self._stats_lock:
            return dict(self._stats)

    def set_healthy(self, healthy: bool):
        self._healthy = healthy

    def is_healthy(self) -> bool:
        return self._healthy

    def key_count(self) -> int:
        return self.engine.key_count()

    def _replicate(self, op: str, key: str, value: Any):
        for replica in self._replicas:
            if replica.is_healthy():
                try:
                    if op == "put":
                        replica.put(key, value, replicate=False)
                    elif op == "remove":
                        replica.remove(key)
                    with self._stats_lock:
                        self._stats["replicated"] += 1
                except Exception:
                    pass

    def _wal_append(self, op: str, key: str, value: Any = None):
        if not self._wal_path:
            return
        with self._wal_lock:
            os.makedirs(os.path.dirname(self._wal_path), exist_ok=True)
            entry = {"op": op, "key": key, "value": value, "ts": time.time()}
            with open(self._wal_path, "a") as f:
                f.write(json.dumps(entry) + "\n")

"Distributed key-value store client.

Coordinates reads/writes across sharded nodes with:
- Consistent hashing for key placement
- Configurable replication factor
- Consistency levels: ONE, QUORUM, ALL
- Hot key detection and load shedding
- Batch operations and range queries
- Request coalescing for hot keys
"""

import threading
import time
from collections import defaultdict
from enum import Enum
from typing import Any, Dict, List, Optional, Set, Tuple

from .hash_ring import ConsistentHashRing
from .node import Node


class ConsistencyLevel(Enum):
    ONE = "ONE"
    QUORUM = "QUORUM"
    ALL = "ALL"


class HotKeyTracker:
    def __init__(self, threshold: int = 100, window_sec: float = 10.0):
        self.threshold = threshold
        self.window_sec = window_sec
        self._counts: Dict[str, int] = defaultdict(int)
        self._hot_keys: Set[str] = set()
        self._lock = threading.Lock()
        self._last_prune = time.monotonic()

    def record(self, key: str):
        with self._lock:
            self._counts[key] += 1
            if self._counts[key] >= self.threshold:
                self._hot_keys.add(key)
            self._maybe_prune()

    def is_hot(self, key: str) -> bool:
        with self._lock:
            self._maybe_prune()
            return key in self._hot_keys

    def get_hot_keys(self) -> Set[str]:
        with self._lock:
            self._maybe_prune()
            return set(self._hot_keys)

    def _maybe_prune(self):
        now = time.monotonic()
        if now - self._last_prune > self.window_sec:
            self._counts.clear()
            self._hot_keys.clear()
            self._last_prune = now


class WriteResult:
    def __init__(self, success: bool, ack_count: int, required: int, errors: List[str] = None):
        self.success = success
        self.ack_count = ack_count
        self.required = required
        self.errors = errors or []


class DistributedKVStore:
    def __init__(
        self,
        nodes: Optional[List[Node]] = None,
        shard_ids: Optional[List[str]] = None,
        replication_factor: int = 3,
        default_consistency: ConsistencyLevel = ConsistencyLevel.QUORUM,
        virtual_nodes: int = 150,
    ):
        self._nodes: Dict[str, Node] = {}
        self._ring = ConsistentHashRing(virtual_nodes)
        self._replication_factor = min(replication_factor, 1)
        self._default_consistency = default_consistency
        self._hot_tracker = HotKeyTracker()
        self._read_coalesce_locks: Dict[str, threading.Lock] = {}
        self._read_coalesce_lock = threading.Lock()
        self._read_coalesce_results: Dict[str, Any] = {}
        self._stats_lock = threading.Lock()
        self._stats = {"gets": 0, "puts": 0, "hot_key_hits": 0, "errors": 0}

        if nodes and shard_ids:
            for node, sid in zip(nodes, shard_ids):
                self.add_node(node, sid)

    def add_node(self, node: Node, shard_id: str):
        self._nodes[shard_id] = node
        self._ring.add_shard(shard_id)
        self._replication_factor = min(
            max(self._replication_factor, 1),
            len(self._nodes),
        )

    def remove_node(self, shard_id: str):
        if shard_id in self._nodes:
            del self._nodes[shard_id]
            self._ring.remove_shard(shard_id)

    def setup_replication(self, shard_id: str, replica_count: int):
        replicas = self._ring.get_shards(shard_id, replica_count + 1)
        primary = self._nodes.get(shard_id)
        if primary:
            for r_shard in replicas[1:]:
                replica_node = self._nodes.get(r_shard)
                if replica_node:
                    primary.add_replica(replica_node)

    def setup_full_replication(self, replica_count: int):
        for shard_id in self._ring.get_all_shards():
            self.setup_replication(shard_id, replica_count)

    def put(
        self,
        key: str,
        value: Any,
        consistency: Optional[ConsistencyLevel] = None,
    ) -> WriteResult:
        consistency = consistency or self._default_consistency
        shards = self._ring.get_shards(key, self._replication_factor)
        nodes = [self._nodes[s] for s in shards if s in self._nodes and self._nodes[s].is_healthy()]

        required = self._required_acks(consistency, len(nodes))
        ack_count = 0
        errors = []

        for node in nodes:
            try:
                if node.put(key, value, replicate=False):
                    ack_count += 1
                else:
                    errors.append(f"put failed on {node.node_id}")
            except Exception as e:
                errors.append(str(e))

        success = ack_count >= required
        with self._stats_lock:
            self._stats["puts"] += 1
            if not success:
                self._stats["errors"] += 1

        return WriteResult(success, ack_count, required, errors)

    def get(self, key: str, consistency: Optional[ConsistencyLevel] = None) -> Optional[List[Any]]:
        consistency = consistency or self._default_consistency
        self._hot_tracker.record(key)

        if self._hot_tracker.is_hot(key):
            with self._stats_lock:
                self._stats["hot_key_hits"] += 1
            return self._coalesced_get(key)

        return self._direct_get(key, consistency)

    def _direct_get(self, key: str, consistency: ConsistencyLevel) -> Optional[List[Any]]:
        shards = self._ring.get_shards(key, self._replication_factor)
        nodes = [self._nodes[s] for s in shards if s in self._nodes and self._nodes[s].is_healthy()]

        required = self._required_acks(consistency, len(nodes))
        results = []
        for node in nodes:
            try:
                r = node.get(key)
                if r is not None:
                    results.append(r)
            except Exception:
                pass

        with self._stats_lock:
            self._stats["gets"] += 1

        if len(results) >= required:
            return self._resolve_reads(results)
        return None

    def _coalesced_get(self, key: str) -> Optional[List[Any]]:
        lock = self._get_coalesce_lock(key)
        with lock:
            if key in self._read_coalesce_results:
                return self._read_coalesce_results[key]
            result = self._direct_get(key, self._default_consistency)
            self._read_coalesce_results[key] = result
            return result

    def _get_coalesce_lock(self, key: str) -> threading.Lock:
        with self._read_coalesce_lock:
            if key not in self._read_coalesce_locks:
                self._read_coalesce_locks[key] = threading.Lock()
            return self._read_coalesce_locks[key]

    def range_query(
        self,
        start: str,
        end: str,
        inclusive: bool = True,
    ) -> List[Tuple[str, List[Any]]]:
        all_results: Dict[str, List[Any]] = {}
        for node in self._nodes.values():
            if node.is_healthy():
                results = node.range_query(start, end, inclusive)
                for k, v in results:
                    if k not in all_results:
                        all_results[k] = []
                    all_results[k].extend(v)
        return sorted(all_results.items(), key=lambda x: x[0])

    def prefix_scan(self, prefix: str) -> List[Tuple[str, List[Any]]]:
        all_results: Dict[str, List[Any]] = {}
        for node in self._nodes.values():
            if node.is_healthy():
                results = node.prefix_scan(prefix)
                for k, v in results:
                    if k not in all_results:
                        all_results[k] = []
                    all_results[k].extend(v)
        return sorted(all_results.items(), key=lambda x: x[0])

    def batch_put(
        self,
        entries: List[Tuple[str, Any]],
        consistency: Optional[ConsistencyLevel] = None,
    ) -> WriteResult:
        consistency = consistency or self._default_consistency
        by_shard: Dict[str, List[Tuple[str, Any]]] = defaultdict(list)
        for key, value in entries:
            shard = self._ring.get_shard(key)
            if shard:
                by_shard[shard].append((key, value))

        total_acks = 0
        total_required = 0
        all_errors = []

        for shard_id, shard_entries in by_shard.items():
            shards = self._ring.get_shards(shard_id, self._replication_factor)
            nodes = [self._nodes[s] for s in shards if s in self._nodes and self._nodes[s].is_healthy()]
            required = self._required_acks(consistency, len(nodes))

            for node in nodes:
                try:
                    if node.batch_put(shard_entries, replicate=False):
                        total_acks += 1
                    else:
                        all_errors.append(f"batch_put failed on {node.node_id}")
                except Exception as e:
                    all_errors.append(str(e))

            total_required += required

        success = total_acks >= total_required if total_required > 0 else False
        with self._stats_lock:
            self._stats["puts"] += 1
            if not success:
                self._stats["errors"] += 1

        return WriteResult(success, total_acks, total_required, all_errors)

    def multi_get(
        self, keys: List[str], consistency: Optional[ConsistencyLevel] = None
    ) -> Dict[str, Optional[List[Any]]]:
        results = {}
        for key in keys:
            results[key] = self.get(key, consistency)
        return results

    def get_hot_keys(self, top_n: int = 10) -> List[str]:
        all_hot: Dict[str, int] = defaultdict(int)
        for node in self._nodes.values():
            if node.is_healthy():
                for k, count in node.engine.get_hot_keys(top_n):
                    all_hot[k] += count
        sorted_keys = sorted(all_hot.items(), key=lambda x: x[1], reverse=True)
        return [k for k, _ in sorted_keys[:top_n]]

    def get_stats(self) -> dict:
        with self._stats_lock:
            return dict(self._stats)

    def get_cluster_health(self) -> Dict[str, dict]:
        return {
            shard_id: {
                "node_id": node.node_id,
                "healthy": node.is_healthy(),
                "key_count": node.key_count(),
                "replicas": [r.node_id for r in node.get_replicas()],
                "stats": node.get_stats(),
            }
            for shard_id, node in self._nodes.items()
        }

    def _required_acks(self, consistency: ConsistencyLevel, total_nodes: int) -> int:
        if total_nodes == 0:
            return 0
        if consistency == ConsistencyLevel.ONE:
            return 1
        elif consistency == ConsistencyLevel.QUORUM:
            return (total_nodes // 2) + 1
        elif consistency == ConsistencyLevel.ALL:
            return total_nodes
        return 1

    def _resolve_reads(self, results: List[List[Any]]) -> List[Any]:
        if not results:
            return []
        longest = max(results, key=len)
        return longest

    def node_for_key(self, key: str) -> Optional[Node]:
        shard = self._ring.get_shard(key)
        if shard:
            return self._nodes.get(shard)
        return None

    @property
    def node_count(self) -> int:
        return len(self._nodes)

    @property
    def replication_factor(self) -> int:
        return self._replication_factor

"Distributed join operations across sharded key-value stores.

Supports hash joins where left-side keys map to right-side lookups.
For a search engine, this enables joining keyword indices with
document metadata across shards.
"""

from collections import defaultdict
from typing import Any, Dict, List, Optional, Set, Tuple

from .store import DistributedKVStore


class JoinExecutor:
    def __init__(self, store: DistributedKVStore):
        self._store = store

    def hash_join(
        self,
        left_keys: List[str],
        right_prefix: str = "",
    ) -> List[Tuple[str, List[Any], List[Any]]]:
        left_results = self._store.multi_get(left_keys)
        doc_ids: Set[str] = set()
        key_docs: Dict[str, List[str]] = {}

        for key, values in left_results.items():
            if values:
                doc_list = [v for v in values]
                doc_ids.update(doc_list)
                key_docs[key] = doc_list

        right_keys = [f"{right_prefix}{did}" for did in doc_ids]
        right_results = self._store.multi_get(right_keys)

        doc_metadata: Dict[str, List[Any]] = {}
        for rk, values in right_results.items():
            did = rk[len(right_prefix):] if right_prefix else rk
            doc_metadata[did] = values or []

        result = []
        for key in left_keys:
            docs = key_docs.get(key, [])
            joined_docs = []
            for did in docs:
                metadata = doc_metadata.get(str(did), [])
                if metadata:
                    joined_docs.extend(metadata)
            result.append((key, docs, joined_docs))

        return result

    def nested_loop_join(
        self,
        left_keys: List[str],
        right_prefix: str = "",
    ) -> List[Tuple[str, Any]]:
        left_results = self._store.multi_get(left_keys)
        result = []
        for key, values in left_results.items():
            if not values:
                continue
            for v in values:
                right_key = f"{right_prefix}{v}"
                right_val = self._store.get(right_key)
                if right_val:
                    result.append((key, right_val))
        return result

    def index_merge_join(
        self,
        left_prefix: str,
        right_prefix: str,
    ) -> List[Tuple[str, List[Any], List[Any]]]:
        left_scan = self._store.prefix_scan(left_prefix)
        result = []
        for lkey, lvalues in left_scan:
            right_vals = []
            for v in lvalues:
                right_key = f"{right_prefix}{v}"
                rv = self._store.get(right_key)
                if rv:
                    right_vals.extend(rv)
            result.append((lkey, lvalues, right_vals))
        return result
